SourceGaussianLaw.literal_source_header:
private theorem partial_charFun (a : ι → ℝ) (s : Finset ι) (t : ℝ) :
    charFun ((coefficientLaw ι).map (fun ω => ∑ i ∈ s, a i * ω i)) t =
      Complex.exp (-((∑ i ∈ s, a i ^ 2 : ℝ) : ℂ) * (t : ℂ) ^ 2 / 2)

SourceKernel.literal_source_header:
private theorem tsum_mode (d : ℕ) (f : SourceMode d → ℝ) (hf : Summable f) :
    (∑' m, f m) = f none + ∑' k : ↥(halfLattice d),
      (f (some (k,false)) + f (some (k,true)))

SourceTorusC4.literal_source_header:
theorem torusSourceField_weakSuperlevel_closed_ae (d : ℕ) (L : ℝ) [Fact (0 < L)] :
    ∀ᵐ sample ∂sourceLaw d, ∀ h : ℝ,
      IsClosed {q : SourceTorus d L | h ≤ torusSourceField d L sample q}
